/** Marca FFCM recebida em 15/10/2026, embutida byte a byte.
 *
 * Estes bytes são exatamente os de `assets/brand/francescato/ffcm-logo-oliva.jpg`: nenhum
 * recorte, redimensionamento, remoção de fundo ou transparência simulada foi aplicado
 * (`docs/projeto/identidade-visual.md`). A cópia existe porque a função servida não lê o
 * diretório de assets em execução; `marca-ffcm.test.ts` falha se os bytes divergirem do
 * arquivo recebido.
 *
 * O JPEG tem fundo branco incorporado e é desenhado apenas sobre área branca do papel.
 * Uma única linha porque é um literal, não código: não há o que ler aqui. */
const MARCA_BASE64 =
  '';
/** Bytes do JPEG recebido. */
export function bytesMarcaFfcm(): Uint8Array {
  const bruto = atob(MARCA_BASE64);
  const bytes = new Uint8Array(bruto.length);
  for (let i = 0; i < bruto.length; i += 1) bytes[i] = bruto.charCodeAt(i);
  return bytes;
}
/** Proporção original recebida: 1006 x 895 pixels. */
export const PROPORCAO_MARCA_FFCM = 895 / 1006;
